<?php
require_once __DIR__.'/../lib/integrations.php';
$id=(int)($argv[1]??0);if(!$id)throw new RuntimeException('Pass a local job ID.');$local=db();$s=$local->prepare('SELECT * FROM jobs WHERE id=?');$s->execute([$id]);$job=$s->fetch();if(!$job)throw new RuntimeException('Job not found.');if($job['external_id']){echo "already_published={$job['external_id']}\n";exit;}$config=integrationConfig('nonceblox_mysql');if(($config['status']??'')!=='configured')throw new RuntimeException('NonceBlox is not configured.');$remote=new PDO('mysql:host='.$config['host'].';port='.($config['port']?:3306).';dbname='.$config['database'].';charset=utf8mb4',$config['username'],integrationSecret($config,'password'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_TIMEOUT=>8]);$duplicate=$remote->prepare('SELECT id FROM career WHERE LOWER(TRIM(title))=LOWER(TRIM(?)) LIMIT 1');$duplicate->execute([$job['title']]);if($duplicate->fetchColumn())throw new RuntimeException('Remote job title already exists.');$skills=array_values(array_unique(array_merge(json_decode($job['required_skills_json']??'[]',true)?:[],json_decode($job['preferred_skills_json']??'[]',true)?:[])));$fields=json_encode(['fname','lname','email','phone','country','state','city','qualification','resume','joining','consent']);$remote->beginTransaction();try{$remote->prepare('INSERT INTO career(title,`desc`,tags,`date`,location,form_fields) VALUES(?,?,?,NOW(),?,?)')->execute([$job['title'],$job['description'],implode(', ',$skills),$job['location']?:'Remote',$fields]);$externalId=(int)$remote->lastInsertId();$slug=trim(preg_replace('/[^A-Za-z0-9]+/','_',$job['title']),'_');$url='https://nonceblox.com/career-inner.php?'.rawurlencode($slug).'='.rawurlencode(base64_encode((string)$externalId));$local->beginTransaction();$local->prepare("UPDATE jobs SET external_id=?,public_url=?,status='open' WHERE id=?")->execute([$externalId,$url,$id]);$userId=$local->query("SELECT id FROM users WHERE role='admin' ORDER BY id LIMIT 1")->fetchColumn()?:null;$local->prepare('INSERT INTO audit_events(user_id,action,entity_type,entity_id,metadata_json) VALUES(?,?,?,?,?)')->execute([$userId,'job_published_nonceblox','job',(string)$id,json_encode(['external_id'=>$externalId,'public_url'=>$url,'channel'=>'cli'])]);$remote->commit();$local->commit();echo "published=$externalId\nurl=$url\n";}catch(Throwable $e){if($remote->inTransaction())$remote->rollBack();if($local->inTransaction())$local->rollBack();throw $e;}
